<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Publiczne linki · '.$page['title']; ?>
<div class="page-head"><div><p class="eyebrow">Udostępnianie</p><h1>Publiczne linki</h1><p class="muted"><?=Html::e($page['title'])?></p></div><a class="button secondary" href="<?=Html::e(Url::to('/pages/'.$page['id']))?>">Wróć do strony</a></div>
<?php if(!$publicEnabled):?><div class="alert warning">Public sharing jest wyłączony globalnie przez administratora.</div><?php endif;?>
<?php if(is_array($newShare??null)&&isset($newShare['url'])):?><div class="alert success"><strong>Link został utworzony. Skopiuj go teraz.</strong><div class="share-once"><input readonly value="<?=Html::e($newShare['url'])?>" onclick="this.select()"></div><?php if($newShare['password_protected']):?><p>Link wymaga ustawionego hasła.</p><?php endif;?></div><?php elseif(is_array($newShare??null)&&isset($newShare['error'])):?><div class="alert danger"><?=Html::e($newShare['error'])?></div><?php endif;?>
<div class="split"><section class="card"><h2>Utwórz link</h2><form method="post" action="<?=Html::e(Url::to('/pages/'.$page['id'].'/public-shares'))?>" class="stack-form"><?=Csrf::field()?><label>Wygaśnięcie (opcjonalne)<input type="date" name="expires_at"></label><label>Hasło (opcjonalne)<input type="password" name="password" minlength="8" autocomplete="new-password"></label><button class="button" <?=$publicEnabled?'':'disabled'?>>Utwórz publiczny link</button></form><p class="muted">Publiczny widok pokazuje wyłącznie tę stronę. Nie zawiera drzewa nawigacji ani innych prywatnych zasobów.</p></section><section class="card"><h2>Aktywne i historyczne linki</h2><?php if(!$shares):?><p class="muted">Nie utworzono jeszcze publicznych linków.</p><?php endif;?><?php foreach($shares as $s):?><div class="list-row"><div><strong><?=Html::e($s['token_prefix'])?>…</strong><small><?=Html::e($s['created_at'])?><?=((int)$s['password_protected']===1)?' · hasło':''?><?=$s['expires_at']?' · wygasa '.Html::e($s['expires_at']):''?><?=$s['revoked_at']?' · unieważniony':''?></small></div><?php if(!$s['revoked_at']):?><form method="post" action="<?=Html::e(Url::to('/pages/'.$page['id'].'/public-shares/'.$s['id'].'/revoke'))?>"><?=Csrf::field()?><button class="link-button danger-text">Unieważnij</button></form><?php endif;?></div><?php endforeach;?></section></div>
